  try {
    var host = (location.hostname || '').toLowerCase();
    if (!(host === 'instagram.com' || host.endsWith('.instagram.com') || host === 'www.instagram.com')) {
      alert('Please open Instagram (www.instagram.com) and try again.');
      return;
    }

    var ON_TOKEN = "__ONAIROS_TOKEN__";
    var ON_EMAIL = "__ONAIROS_EMAIL__";

    var consent = window.confirm(
      'Onairos Instagram Export\\n\\n' +
      'Allow Onairos to export your Instagram engagement?\\n\\n' +
      '- Your liked posts\\n' +
      '- Your saved posts\\n' +
      '- Your collections\\n\\n' +
      'Your data is encrypted and only used to build your personal AI model.'
    );

    if (!consent) {
      console.log('Onairos Instagram export cancelled by user.');
      return;
    }

    console.log('Onairos Instagram export consent granted. Extracting data...');

    /* Cookie check removed - sessionid is HttpOnly */

    function extractLikes() {
      var likes = [];
      var likeElements = document.querySelectorAll('[data-testid*="like"], article, [role="article"]');
      likeElements.forEach(function(el, idx) {
        if (idx >= 50) return;
        
        var imgEl = el.querySelector('img[src*="cdninstagram"]');
        var captionEl = el.querySelector('[class*="caption"], span');
        var usernameEl = el.querySelector('a[href*="/"]');
        
        if (imgEl || captionEl) {
          likes.push({
            id: 'like_' + idx,
            type: 'like',
            mediaType: imgEl ? 'image' : 'text',
            caption: captionEl ? captionEl.textContent.slice(0, 200) : null,
            owner: usernameEl ? usernameEl.textContent.replace('@', '') : null,
            url: imgEl ? imgEl.src : null
          });
        }
      });
      return likes;
    }

    function extractSaves() {
      var saves = [];
      var saveElements = document.querySelectorAll('[data-testid*="saved"], [class*="saved"]');
      saveElements.forEach(function(el, idx) {
        if (idx >= 50) return;
        
        var imgEl = el.querySelector('img');
        var captionEl = el.querySelector('span');
        
        saves.push({
          id: 'save_' + idx,
          type: 'save',
          mediaType: imgEl ? 'image' : 'video',
          caption: captionEl ? captionEl.textContent.slice(0, 200) : null,
          url: imgEl ? imgEl.src : null
        });
      });
      return saves;
    }

    function extractCollections() {
      var collections = [];
      var collectionElements = document.querySelectorAll('[data-testid*="collection"], [class*="collection"]');
      collectionElements.forEach(function(el, idx) {
        var nameEl = el.querySelector('span, h2, h3');
        var countEl = el.querySelector('[class*="count"]');
        var coverEl = el.querySelector('img');
        
        collections.push({
          id: 'collection_' + idx,
          name: nameEl ? nameEl.textContent.trim() : 'Collection ' + (idx + 1),
          mediaCount: countEl ? parseInt(countEl.textContent) || 0 : 0,
          coverUrl: coverEl ? coverEl.src : null
        });
      });
      return collections;
    }

    /* Get user ID from page */
    function getUserId() {
      try {
        var scripts = document.querySelectorAll('script');
        for (var i = 0; i < scripts.length; i++) {
          var text = scripts[i].textContent;
          var match = text.match(/"userId":"(\\d+)"/);
          if (match) return match[1];
        }
        return null;
      } catch(e) {
        return null;
      }
    }

    /* Extract all data */
    var likes = extractLikes();
    var saves = extractSaves();
    var collections = extractCollections();
    var userId = getUserId();

    /* Build payload */
    var payload = {
      platform: 'mobile-instagram',
      dataType: 'social',
      data: {
        likes: likes,
        saves: saves,
        collections: collections,
        instagramUserId: userId
      },
      summary: {
        likeCount: likes.length,
        saveCount: saves.length,
        collectionCount: collections.length,
        totalEngagements: likes.length + saves.length
      },
      mobileMetadata: {
        platform: 'web',
        source: 'bookmarklet',
        extractedAt: new Date().toISOString()
      }
    };

    /* Create Overlay UI */
    var d = document.createElement('div');
    d.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.85);z-index:2147483647;display:flex;flex-direction:column;align-items:center;justify-content:center;font-family:-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;';
    d.innerHTML = 
      '<div style="background:#1e1e1e;padding:24px;border-radius:16px;width:90%;max-width:360px;text-align:center;box-shadow:0 20px 50px rgba(0,0,0,0.5);border:1px solid rgba(255,255,255,0.1);">' +
        '<h2 style="margin:0 0 8px;color:white;font-size:20px;font-weight:600;">Data Ready</h2>' +
        '<p style="margin:0 0 20px;color:#a8a8a8;font-size:14px;">' + 
          likes.length + ' likes \u2022 ' + saves.length + ' saves' +
        '</p>' +
        '<div style="display:flex;flex-direction:column;gap:12px;">' +
          '<button id="btn-sync" style="padding:14px;background:linear-gradient(45deg, #f09433, #bc1888);border:none;border-radius:12px;color:white;font-weight:600;font-size:16px;cursor:pointer;">' +
            'Sync Now' +
          '</button>' +
          '<button id="btn-close" style="padding:10px;background:transparent;border:none;color:#666;font-size:14px;cursor:pointer;margin-top:8px;">' +
            'Close' +
          '</button>' +
        '</div>' +
        '<p id="status-msg" style="margin:16px 0 0;font-size:12px;color:#666;line-height:1.4;">' +
          'Sync opens a popup to send data to Onairos.' +
        '</p>' +
      '</div>';
    
    document.body.appendChild(d);

    var btnSync = document.getElementById('btn-sync');
    var btnClose = document.getElementById('btn-close');
    var statusMsg = document.getElementById('status-msg');

    btnSync.onclick = function() {
      if (!ON_TOKEN || ON_TOKEN === '__ONAIROS_TOKEN__') {
        statusMsg.innerText = 'No token found. Please log in to Onairos.';
        statusMsg.style.color = '#ef4444';
        return;
      }

      btnSync.innerText = 'Opening Popup...';
      
    /* Popup Logic */
    var html = '<!DOCTYPE html><html><head><title>Syncing...</title></head>' +
      '<body style="background:#111;color:#fff;display:flex;justify-content:center;align-items:center;height:100vh;font-family:sans-serif;">' +
      '<div><h2>Syncing...</h2><div id="s">Connecting...</div></div>' +
      '<script>' +
      'var d=' + JSON.stringify(payload) + ';var t="' + ON_TOKEN + '";' +
      'fetch("__ONAIROS_BASE_URL__/platform-data/store",{method:"POST",headers:{"Content-Type":"application/json","Authorization":"Bearer "+t},body:JSON.stringify(d)})' +
      '.then(r=>{if(!r.ok)throw new Error(r.status);return r.json()})' +
      '.then(()=>{document.getElementById("s").innerText="\u2705 Done!";setTimeout(()=>window.close(),1000)})' +
      '.catch(e=>{document.getElementById("s").innerText="\u274C "+e.message});' +
      '<\/script></body></html>';

    /* Try Blob URL first */
    try {
      var blob = new Blob([html], {type: 'text/html'});
      var url = URL.createObjectURL(blob);
      var win = window.open(url, '_blank', 'width=400,height=400');
      if(!win) throw new Error('Popup blocked');
    } catch(e) {
      /* Fallback to Data URI if Blob fails */
      console.log('Blob failed, trying Data URI');
      window.open('data:text/html;charset=utf-8,' + encodeURIComponent(html), '_blank', 'width=400,height=400');
    }
    };

    btnClose.onclick = function() {
      d.remove();
    };

  } catch(e) {
    console.error('[Onairos Instagram] Error:', e);
    alert('\u274C Onairos Instagram error: ' + (e && e.message ? e.message : e));
  }
